  &DefaultButton;




function filter$changepassword(p){
  this.constructor(p);
}
filter$changepassword.prototype = new DirEvent();
filter$changepassword.prototype.afterInit = function(){
  var p = this._dir;
  p.jObject('old_pass').attr('type', 'password');
  p.jObject('new_pass').attr('type', 'password');
  p.jObject('confirm_pass').attr('type', 'password');
}
filter$changepassword.prototype.buttonDialogClick = function(id){
  var p = this._dir;
  if (id == 'filterOk') {
    this.checkNotBlank(function(m){
      p.request('changepass', 'GetRow', m);
    });
  } else {
    DirEvent.prototype.buttonDialogClick.apply(this, arguments);
  }
}








